using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using C=System.Windows.Controls;
using W=System.Windows;
namespace ProjectPoeLedger;
internal sealed class PriceOverlay : W.Window {
 readonly NativeStore store; readonly MarketService market; readonly Func<string> league; readonly Func<Dictionary<string,string>> readSave; readonly string token; readonly Action<string> openTrade;
 readonly C.TextBlock title=new(){FontSize=22,TextWrapping=W.TextWrapping.Wrap}, result=new(){TextWrapping=W.TextWrapping.Wrap}, details=new(){TextWrapping=W.TextWrapping.Wrap};
 readonly C.Button live=new(){Content="Quote comparable listings",Padding=new Thickness(8),Margin=new Thickness(0,6,0,0)};
 readonly C.TextBox raw=new(){AcceptsReturn=true,Height=100,VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto};
 readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(60)};
 string name="", type="", rarity="", selectedLeague=""; bool valid,corrupted,busy; int generation;
 public PriceOverlay(NativeStore store,MarketService market,Func<string> league,Func<Dictionary<string,string>> readSave,string token,Action<string> openTrade){this.store=store;this.market=market;this.league=league;this.readSave=readSave;this.token=token;this.openTrade=openTrade;
 Title="Poe Ledger — Quick price check";Width=465;Height=515;MinWidth=340;MinHeight=350;Topmost=true;WindowStartupLocation=W.WindowStartupLocation.CenterScreen;ShowInTaskbar=false;Background=new SolidColorBrush(System.Windows.Media.Color.FromRgb(16,23,34));Foreground=System.Windows.Media.Brushes.Gainsboro;
 try{Icon=new System.Windows.Media.Imaging.BitmapImage(new Uri(Path.Combine(AppContext.BaseDirectory,"Web","poe-ledger.png")));}catch{}
 var p=new C.StackPanel{Margin=new Thickness(16)};Content=new C.ScrollViewer{Content=p,VerticalScrollBarVisibility=C.ScrollBarVisibility.Auto};p.Children.Add(new C.TextBlock{Text="POE LEDGER  /  QUICK PRICE CHECK",Margin=new Thickness(0,0,0,10)});p.Children.Add(title);p.Children.Add(details);p.Children.Add(result);p.Children.Add(live);live.Click+=async (_,_)=>await Quote();
 Add(p,"Read clipboard again",Read);Add(p,"Open full Trade importer",()=>{Hide();openTrade(raw.Text);});var pin=new C.CheckBox{Content="Always on top",IsChecked=true,Foreground=Foreground,Margin=new Thickness(0,8,0,8)};pin.Checked+=(_,_)=>Topmost=true;pin.Unchecked+=(_,_)=>Topmost=false;p.Children.Add(pin);p.Children.Add(raw);raw.TextChanged+=(_,_)=>Parse();Add(p,"Hide overlay (Esc)",Hide);PreviewKeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Escape){Hide();e.Handled=true;}};Closed+=(_,_)=>{generation++;http.Dispose();}; }
 static void Add(C.Panel p,string label,Action action){var b=new C.Button{Content=label,Padding=new Thickness(8),Margin=new Thickness(0,6,0,0)};b.Click+=(_,_)=>{try{action();}catch(Exception e){W.MessageBox.Show(e.Message);}};p.Children.Add(b);}
 public void ShowItem(){Show();Activate();Read();}
 void Read(){try{raw.Text=W.Clipboard.ContainsText()?W.Clipboard.GetText():"";Parse();}catch(Exception e){result.Text="Clipboard unavailable: "+e.Message;}}
 void Parse(){generation++;valid=false;live.IsEnabled=false;name=type=rarity="";selectedLeague=league();title.Text="Copy an item in PoE";details.Text=selectedLeague;result.Text="No market requests sent.";var lines=raw.Text.Split('\n').Select(x=>x.Trim()).ToArray();int i=Array.FindIndex(lines,x=>x.StartsWith("Rarity: ",StringComparison.Ordinal));if(i<0||i+1>=lines.Length||lines[i+1].Length==0)return;rarity=lines[i][8..].ToLowerInvariant();name=lines[i+1];type=rarity=="unique"&&i+2<lines.Length?lines[i+2]:name;corrupted=lines.Contains("Corrupted");bool unid=lines.Contains("Unidentified");title.Text=name;details.Text=$"{selectedLeague} • {rarity} • {type}"+(corrupted?" • Corrupted":"");
 if(unid||rarity is not ("unique" or "currency")){result.Text="Use the full Trade importer for unidentified items, equipment affixes, gems or other variants.";return;}
 var rows=store.Rows("SELECT boss,price,seen FROM item_prices WHERE league=$p0 AND name=$p1 COLLATE NOCASE ORDER BY price",selectedLeague,name);result.Text=rows.Count==0?"No exact-name saved price.":"Saved name matches (not variant-specific):\n"+string.Join("\n",rows.Take(5).Select(r=>$"{r["boss"]}: {r["price"]} c"));
 valid=type.Length>0&&type!="--------";live.IsEnabled=valid&&!busy;}
 async System.Threading.Tasks.Task Quote(){if(!valid||busy)return;if(!market.Online){result.Text="Enable online market requests in the main window first.";return;}if(selectedLeague!=league()){Parse();result.Text="League changed. Review the item and click again.";return;}if(W.MessageBox.Show("Request comparable asking prices? Special variants, rolls, sockets and modifiers are not matched. Existing cooldown applies.","Poe Ledger",W.MessageBoxButton.YesNo)!=W.MessageBoxResult.Yes)return;
 int current=generation;busy=true;live.IsEnabled=false;result.Text="Requesting comparable asking prices…";try{using var doc=JsonDocument.Parse(readSave().GetValueOrDefault("bossledger-v4","{}"));double rate=EconomyViews.N(doc.RootElement,"rate")??0;if(!double.IsFinite(rate)||rate<=0)throw new Exception("Set Chaos per Divine in the main calculator first.");var filters=new Dictionary<string,object>();if(rarity=="unique"){filters["type_filters"]=new{filters=new{rarity=new{option="unique"}}};filters["misc_filters"]=new{filters=new{identified=new{option="true"},corrupted=new{option=corrupted?"true":"false"}}};}var q=new Dictionary<string,object>{{"status",new{option="available"}},{"type",type},{"stats",new[]{new{type="and",filters=Array.Empty<object>()}}},{"filters",filters}};if(rarity=="unique")q["name"]=name;var payload=JsonSerializer.Serialize(new{league=selectedLeague,rate,mode="pob28",query=new{query=q,sort=new{price="asc"}}});using var req=new HttpRequestMessage(HttpMethod.Post,Program.Origin+"/api/trade-quote");req.Headers.Add("X-Ledger-Token",token);req.Headers.Add("Origin",Program.Origin);req.Content=new StringContent(payload,Encoding.UTF8,"application/json");using var response=await http.SendAsync(req);using var data=JsonDocument.Parse(await response.Content.ReadAsStringAsync());if(current!=generation)return;if(!response.IsSuccessStatusCode)throw new Exception(data.RootElement.TryGetProperty("error",out var error)?error.ToString():$"HTTP {(int)response.StatusCode}");double price=data.RootElement.GetProperty("price").GetDouble();int sample=data.RootElement.GetProperty("sample").GetInt32();result.Text=$"Comparable asking-price estimate: {price:0.##} c ({price/rate:0.##} D)\n{sample} sellers • possibly cached • not a valuation of exact rolls or variants.";}catch(Exception e){if(current==generation)result.Text=e.Message;}finally{busy=false;live.IsEnabled=valid;}}
}
